import {derive,encryptVault,decryptVault,wrapBotKey,lookupTokens} from './vault.js';
const icons={
 home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
 folder:'<path d="M3 7V5h7l2 3h9v12H3Z"/>',
 note:'<path d="M6 3h9l4 4v14H6Z"/><path d="M14 3v5h5M9 12h7M9 16h5"/>',
 document:'<path d="M6 3h9l4 4v14H6Z"/><path d="M14 3v5h5M9 12h7M9 16h5"/>',
 photo:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="9" cy="9" r="2"/><path d="m3 17 5-4 4 4 4-6 5 7"/>',
 link:'<path d="m10 13 4-4M8 16l-1 1a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0M16 8l1-1a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0" transform="translate(0 -1) scale(.95)"/>',
 voice:'<path d="M5 9v6M9 5v14M13 8v8M17 3v18M21 9v6"/>',
 lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',
 settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
 back:'<path d="M19 12H5m5-5-5 5 5 5"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 check:'<path d="m5 12 4 4L20 5"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
 trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',
 edit:'<path d="m14 5 5 5M4 20l1-6L16 3l5 5-11 11Z"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',
 copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',
 eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12"/><circle cx="12" cy="12" r="3"/>',
 inbox:'<path d="M5 3h14l3 12v6H2v-6ZM2 15h6l2 3h4l2-3h6"/>',
 upload:'<path d="M12 17V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',
 archive:'<rect x="3" y="3" width="18" height="5" rx="1"/><path d="M5 8v13h14V8M9 12h6"/>'
};icons.audio=icons.voice;icons.video='<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m10 9 5 3-5 3Z"/>';
const ic=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.document}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=t=>new Intl.DateTimeFormat('ru',{day:'numeric',month:'short'}).format(new Date(t*1000));
const state={me:null,page:'home',group:'',kind:'',docType:'',q:'',items:[],total:0,offset:0,detail:null,request:0,navigation:0,searchMode:'recent',searchWarning:''};
let telegram=null,initData='',toastTimer,vaultTimer,activePreview=null,searchTimer,lastFocus;
let unlocked=null,vaultData={version:0,envelope:null};

async function api(path,options={}){
 const headers={'X-Iz-Request':'1',...(initData?{Authorization:'tma '+initData}:{}),...(options.headers||{})};
 if(options.body&&!(options.body instanceof FormData)){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body)}
 const response=await fetch('/api'+path,{...options,headers,credentials:'same-origin'});
 if(!response.ok){let d;try{d=await response.json()}catch{}throw Error(d?.detail||'Не удалось выполнить действие. Попробуй ещё раз.')}
 return response.status===204?null:response.json();
}
function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',3600)}
function error(text){toast(text)}
function pill(g){return `<span class="pill">${esc(g)}</span>`}
function itemCard(i){return `<button class="item" data-action="item" data-id="${esc(i.id)}"><span class="item-icon ${esc(i.kind)}">${ic(i.kind)}</span><span class="item-content"><span class="item-title">${esc(i.title)}</span><span class="item-desc">${esc(i.snippet||i.context||i.body||i.extraction||'Оригинал сохранён')}</span>${(i.groups.length?i.groups:['Неразобранное']).map(pill).join('')}${i.source_label?'<span class="pill test">Тестовая запись</span>':''}</span><span class="item-meta">${date(i.created)}<br>${i.match?esc(i.match):i.kind==='photo'?'Фото':i.kind==='document'?'Документ':'Сохранение'}</span>${ic('arrow')}</button>`}
function collection(g,n,k){return `<button class="collection ${k%3===1?'purple':k%3===2?'orange':''}" data-action="group" data-group="${esc(g)}"><span class="folder-icon">${ic(g==='Неразобранное'?'inbox':'folder')}</span><span class="count">${n}</span><h3>${esc(g)}</h3><p>${g==='Неразобранное'?'Можно добавить контекст':'Всё по этой теме'}</p><span class="arrow">${ic('arrow')}</span></button>`}
function empty(title,desc,action='add',label='Добавить материал'){return `<div class="empty"><div class="big-icon">${ic('inbox')}</div><h3>${esc(title)}</h3><p>${esc(desc)}</p>${action?`<button class="primary" data-action="${action}">${ic('plus')}${esc(label)}</button>`:''}</div>`}
function nav(mobile=false){const p=state.page;return `<nav class="${mobile?'mobile-nav':'nav'}" aria-label="Основная навигация">${[['home','home','Главная'],['collections','folder','Подборки'],['vault','lock','Пароли'],['settings','settings','Настройки']].map(([v,i,t])=>`<button data-action="nav" data-page="${v}" class="${p===v?'active':''}">${ic(i)}<span>${t}</span>${!mobile&&v==='collections'?`<span class="count">${state.me.total}</span>`:''}</button>`).join('')}</nav>`}
function searchHint(){if(state.searchWarning&&state.q)return state.searchWarning;if(state.q&&state.searchMode==='gemini')return 'Найдено по смыслу · Gemini';if(state.q&&state.searchMode==='keyword')return 'Поиск по словам';return state.me.search_provider==='gemini'?'Поиск по смыслу · Gemini':state.me.ai_ready?'Поиск по словам и описанию · на Mac':'Поиск по словам'}
function searchForm(){return `<form id="search-form"><div class="searchbox">${ic('search')}<input id="search" name="q" aria-label="Поиск по сохранённому" placeholder="${state.group?'Найти в подборке…':'Что ты хочешь найти?'}" value="${esc(state.q)}" autocomplete="off"><button class="icon-button" type="submit" aria-label="Найти">${ic('arrow')}</button></div></form>`}
function list(){return `<div class="items">${state.items.map(itemCard).join('')}</div>${state.items.length<state.total?'<div class="actions"><button class="secondary" data-action="more">Показать ещё</button></div>':''}`}
function hero(title,sub,add=true){return `<div class="hero"><div><h1>${esc(title)}</h1><p class="sub">${esc(sub)}</p></div>${add?`<button class="primary" data-action="add" aria-label="Добавить материал">${ic('plus')}<span>Добавить</span></button>`:''}</div>`}
function home(){const gs=Object.entries(state.me.groups).sort((a,b)=>b[1]-a[1]);return `<div class="hero home-hero"><h1>Всё важное — рядом.</h1><button class="primary" data-action="add" aria-label="Добавить материал">${ic('plus')}</button></div>${searchForm()}${state.q&&state.searchWarning?`<p class="searchhint">${esc(state.searchWarning)}</p>`:''}${state.q?`<div class="section-head"><h2>Результаты</h2><span>${state.total} найдено</span></div>${state.total?list():empty('Пока ничего не нашлось','Попробуй другое название или фразу из материала.','','')}`:`<div class="section-head"><h2>Твои подборки</h2><button class="ghost small" data-action="nav" data-page="collections">Все подборки ${ic('arrow')}</button></div>${gs.length?`<div class="collections">${gs.slice(0,6).map(([g,n],k)=>collection(g,n,k)).join('')}</div>`:empty('Здесь появится порядок','Перешли что-нибудь боту или добавь первый материал с этого экрана.')}<div class="section-head"><h2>Недавно сохранённое</h2><span>${state.me.total} всего</span></div>${state.items.length?list():''}`}`}
function collectionFilters(){const types=Object.entries(state.me.group_types?.[state.group]||{});const formats=[['','Все форматы'],['document','Документы'],['photo','Фото'],['note','Заметки'],['link','Ссылки'],['voice','Голосовые'],['audio','Аудио'],['video','Видео']];return `<div class="compact-filters" aria-label="Фильтры материалов"><label class="filter-field"><span>Назначение</span><select id="purpose-filter" class="${state.docType?'selected':''}" aria-label="Назначение материала"><option value="">Все назначения</option>${types.map(([t,n])=>`<option value="${esc(t)}" ${state.docType===t?'selected':''}>${esc(t)} · ${n}</option>`).join('')}</select></label><label class="filter-field"><span>Формат</span><select id="format-filter" class="${state.kind?'selected':''}" aria-label="Формат материала">${formats.map(([v,t])=>`<option value="${v}" ${state.kind===v?'selected':''}>${t}</option>`).join('')}</select></label>${state.docType||state.kind?`<button class="icon-button reset-filters" data-action="reset-filters" aria-label="Сбросить фильтры" title="Сбросить фильтры">${ic('close')}</button>`:''}</div>`}
function collections(){if(!state.group)return `${hero('Подборки','Одна папка на тему. Учебники, конспекты и другие материалы собраны внутри вместе.')}${Object.keys(state.me.groups).length?`<div class="collections">${Object.entries(state.me.groups).sort((a,b)=>b[1]-a[1]).map(([g,n],k)=>collection(g,n,k)).join('')}</div>`:empty('Подборок ещё нет','Добавь первый материал. Если его назначение понятно, появится подходящая подборка.')}`;
 return `<button class="back" data-action="nav" data-page="collections">${ic('back')}Все подборки</button>${hero(state.group,state.group==='Неразобранное'?'Материалы, которым пока не хватает понятного контекста.':'Документы, заметки и ссылки по одной теме.')}${searchForm()}${state.q?`<p class="searchhint">${esc(searchHint())}</p>`:''}${collectionFilters()}<div class="section-head"><h2>${state.q?'Результаты':'Материалы'}</h2><span>${state.total}</span></div>${state.total?list():empty('Здесь пока пусто','Попробуй изменить фильтр или поиск.',false)}${state.q?'<button class="ghost" data-action="search-all">Искать во всех подборках</button>':''}`}

function safeSource(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?esc(u.href):'#'}catch{return '#'}}
function phoneBanner(){const p=state.me?.phone_access||{};return `<div id="phone-status">${p.required&&!p.ready?`<div class="inline-note" role="status">Подборки на телефоне пока недоступны. ${esc(p.error||'Подключаю внешний адрес и обновляю кнопку Telegram…')}${state.me.local?'<div class="actions"><button class="secondary small" data-action="reconnect-phone">Восстановить подключение</button></div>':''}</div>`:''}</div>`}
function learningBanner(){const l=state.me?.learning||{};return ['queued','running'].includes(l.status)?`<div class="inline-note learning-status" role="status">${ic('info')} ${l.mode==='rebuild'?'Заново читаю доступные оригиналы и обновляю подборки…':'Учитываю твоё пояснение и пересматриваю похожие материалы…'} Проверено: ${l.checked||0}, обновлено: ${l.changed||0}.</div>`:''}
function analysisPanel(i){const a=i.analysis||{};const sources=a.web?.sources||[];return `<section class="paper"><h3>Как разобран материал</h3>${i.analysis_state==='unreadable'?'<p class="form-note">Оригинал сохранён, но его содержимое пока не удалось прочитать. Название и формат учтены; можно добавить пояснение.</p>':''}${i.analysis_state==='retry_pending'?'<p class="form-note" role="status">Облачный разбор не завершён. Автоматически повторю попытку; файл уже сохранён.</p>':''}${a.needs_context?'<p class="form-note">Для точного разбора нужно пояснение'+(a.uncertainties?.length?': '+esc(a.uncertainties.join('; ')):'.')+'</p>':''}${i.analysis_state==='needs_original'?'<p class="form-note">Содержимое пока не прочитано: есть только название. Для анализа нужен оригинал или пояснение.</p>':''}${a.cloud?.error?`<p class="form-note">${esc(a.cloud.error)}</p>`:''}${a.cloud?.review_error?`<p class="form-note">${esc(a.cloud.review_error)}</p>`:''}${a.summary?`<p>${esc(a.summary)}</p>`:''}<div class="analysis-facts">${a.document_type?pill(a.document_type):''}${a.subject?pill(a.subject):''}${a.cloud?.reviewed?pill('Дополнительная проверка'):''}${a.cloud?.cached?pill('Повтор без нового запроса'):''}${a.method==='gemini'?pill('Gemini 3.8 Flash')+(a.cloud?.images?pill('Изображений: '+a.cloud.images):''):''}${a.memory_examples_used?pill('Учтены твои прошлые пояснения: '+a.memory_examples_used):''}</div>${a.evidence?.length?`<p class="form-note">Основание в содержимом:</p>${a.evidence.slice(0,2).map(e=>`<div class="context">${esc(e)}</div>`).join('')}`:''}${sources.length?`<details><summary>Справка по теме в интернете</summary><p class="form-note">Искал только общий тип материала. Личный текст не отправлялся в поиск. Это справочные источники, а не гарантия правильности.</p>${sources.map(x=>`<p><a href="${safeSource(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)}</a>${x.extract?'<span class="form-note"> · Прочитана страница</span>':''}</p>`).join('')}</details>`:['unavailable','no_results','no_safe_query','disabled'].includes(a.web?.status)?'<p class="form-note">'+({unavailable:'Справочные источники временно недоступны; вывод требует уточнения.',no_results:'В интернете не найдено подходящих справочных источников.',no_safe_query:'Для поиска не удалось выделить общий термин без личных данных.',disabled:'Проверка в интернете выключена.'}[a.web.status])+'</p>':''}<div class="actions"><button class="secondary small" data-action="analyse-again">${ic('search')}Прочитать заново</button>${!i.has_local_file&&['document','photo','audio','voice','video'].includes(i.kind)?'<button class="secondary small" data-action="attach-original">'+ic('upload')+'Добавить оригинал</button>':''}</div><p class="form-note">Пояснение помогает также пересмотреть другие похожие записи. Чтобы удалить эту запись, напиши «удалить» в пояснении.</p></section>`}

function detail(){const i=state.detail;return `<button class="back" data-action="back">${ic('back')}Назад</button><div class="readable"><div class="detail-head"><span class="item-icon ${esc(i.kind)}">${ic(i.kind)}</span><div><h1>${esc(i.title)}</h1><div class="detail-meta">${date(i.created)} · ${i.source_label?esc(i.source_label):'Личное сохранение'}</div>${(i.groups.length?i.groups:['Неразобранное']).map(pill).join('')}</div></div>${i.source_label?'<div class="inline-note">Это тестовая запись с экрана Telegram. Оригинал вложения не импортирован; текст мог быть переписан частично.</div>':''}<div class="actions">${i.has_local_file?`<button class="primary" data-action="download" data-id="${i.id}">${ic('download')}Скачать оригинал</button>`:''}${state.me.bot_configured&&state.me.id>0&&(i.has_file||i.body)?`<button class="secondary" data-action="send" data-id="${i.id}">${i.has_file?'Получить в Telegram':'Отправить текст в Telegram'}</button>`:''}<button class="secondary" data-action="edit">${ic('edit')}Изменить</button><button class="ghost" data-action="delete">${ic('trash')}В корзину</button></div>${i.has_file&&['photo','audio','voice','video'].includes(i.kind)?'<div id="preview"></div>':''}${i.context?`<section class="paper"><h3>Твоё пояснение</h3><div class="context">${esc(i.context)}</div></section>`:`<div class="paper"><h3>Добавь контекст</h3><p class="sub">Пара слов поможет найти этот материал позже.</p><div class="actions"><button class="secondary small" data-action="edit">${ic('plus')}Добавить пояснение</button></div></div>`}${analysisPanel(i)}<section class="paper"><h3>${i.kind==='photo'?'Распознанный текст':i.kind==='note'||i.kind==='link'?'Содержимое':'Извлечённый текст'}</h3><div class="body-text">${linkify(i.body)||'<span class="sub">Текста пока нет. Оригинал можно получить отдельно или добавить пояснение.</span>'}</div></section>${i.extraction?`<div class="note-line">${ic('info')}<span>${esc(i.extraction)}</span></div>`:''}<p class="form-note">${i.manual_groups?'Подборки выбраны тобой. Автосортировка их не изменит.':'Подборки определяются по содержимому и твоим прошлым пояснениям. Их можно исправить.'}</p></div>`}
function linkify(t){return esc(t).replace(/https?:\/\/[^\s<>]+/g,url=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${url}</a>`)}
function geminiPanel(){const m=state.me;if(!m.local)return '';const g=m.gemini||{},u=g.usage||{};const active=m.analysis_provider==='gemini';return `<section class="paper"><h3>Gemini 3.8 Flash</h3><p class="sub">${active?'Включена для следующих разборов.':'Подключи анализ фотографий и документов через Google.'}</p><p class="form-note">Gemini получит текст, пояснение, подходящие личные примеры и саму фотографию. Для PDF отправляются изображения только первых ${m.pdf_pages||4} страниц. Парольное хранилище не передаётся.</p><p class="form-note">За ${esc(u.month||'месяц')}: оценка $${Number(u.estimated_usd||0).toFixed(3)}, резерв $${Number(u.reserved_usd||0).toFixed(3)}. Запросов: ${u.requests||0}, с ошибкой: ${u.failed_requests||0}.</p>${g.error?`<p class="form-error">${esc(g.error)}</p>`:''}<form id="gemini-form"><label for="gemini-key">API-ключ из Google AI Studio</label><input class="input" type="password" id="gemini-key" name="key" autocomplete="off" spellcheck="false" maxlength="250" placeholder="${g.key_configured?'Ключ сохранён; оставь пустым, чтобы использовать его':'Вставь ключ сюда, не в Telegram'}"><label for="gemini-budget">Лимит программы на месяц, USD</label><input class="input" type="number" id="gemini-budget" name="monthly_limit_usd" min="0.01" max="1000" step="0.01" value="${Number(g.monthly_limit_usd||5)}" required><p class="form-note">Общий лимит для владельца и тестировщиков. Считаем токены перед платным запросом и резервируем стоимость ответа. Это контроль программы и оценка, а не банковский лимит Google. Статистику проекта проверяй также в Google.</p><p class="form-note">Для личного архива рекомендуем платный Standard. На бесплатном тарифе Google может использовать материалы для улучшения продуктов. Тариф включается в Google AI Studio; программа его не меняет и не определяет.</p><div id="form-error" class="form-error" role="alert"></div><div class="actions"><button class="primary" type="submit">Сохранить и подключить</button>${active?'<button type="button" class="secondary" data-action="gemini-off">Переключить на локальную модель</button>':''}</div></form><p class="form-note"><a href="https://aistudio.google.com/api-keys" target="_blank" rel="noopener noreferrer">Создать API-ключ</a> · <a href="https://ai.google.dev/gemini-api/docs/pricing" target="_blank" rel="noopener noreferrer">Тарифы Google</a></p><p class="form-note">Ключ сохраняется только на этом Mac, не показывается повторно и не включается в экспорт. Подключение само по себе не отправляет старый архив: повторный разбор запускается отдельно.</p></section>`}
function provodPanel(){const m=state.me;if(!m.local)return '';const p=m.provod||{},u=p.usage||{};const active=m.analysis_provider==='provod';return `<section class="paper"><h3>Gemini через Provod</h3><p class="sub">${active?'Подключено: Gemini 3.8 Flash.':'Анализ фотографий и документов с оплатой в рублях.'}</p><p class="form-note">Отправляются текст, пояснение, подходящие личные примеры и фото. Для PDF — изображения первых ${m.pdf_pages||4} страниц. Парольное хранилище не передаётся.</p><p class="form-note">За ${esc(u.month||'месяц')}: оценка ${Number(u.estimated_rub||0).toFixed(2)} ₽, резерв ${Number(u.reserved_rub||0).toFixed(2)} ₽. Запросов: ${u.requests||0}, с ошибкой: ${u.failed_requests||0}.</p>${p.error?`<p class="form-error">${esc(p.error)}</p>`:''}<form id="provod-form"><label for="provod-key">API-ключ Provod</label><input class="input" type="password" id="provod-key" name="key" autocomplete="off" spellcheck="false" maxlength="250" placeholder="${p.key_configured?'Ключ сохранён; можно оставить пустым':'Вставь ключ сюда'}"><label for="provod-budget">Лимит программы на месяц, ₽</label><input class="input" type="number" id="provod-budget" name="monthly_limit_rub" min="1" max="100000" step="1" value="${Number(p.monthly_limit_rub||1000)}" required><p class="form-note">Общий лимит владельца и тестировщиков. Перед запросом резервируем оценку текста, изображений и ответа. Тариф для оценки: ${Number(p.input_price||61)} ₽ за миллион входных и ${Number(p.output_price||303)} ₽ за миллион выходных токенов. Фактические списания проверяй в Provod: тарифы, кеш и рассуждения могут изменить сумму. Неопределённый расход после обрыва остаётся в резерве.</p><div id="form-error" class="form-error" role="alert"></div><div class="actions"><button class="primary" type="submit">Сохранить и подключить Provod</button>${active?'<button type="button" class="secondary" data-action="gemini-off">Переключить на локальную модель</button>':''}</div></form><p class="form-note"><a href="https://app.provod.ai/api-keys" target="_blank" rel="noopener noreferrer">API-ключи Provod</a> · <a href="https://app.provod.ai/usage" target="_blank" rel="noopener noreferrer">Фактические расходы</a></p><p class="form-note">Ключ хранится только на этом Mac, скрыт в интерфейсе и не входит в экспорт. Подключение не запускает повторный разбор старого архива.</p></section>`}
function settings(){const m=state.me;return `${hero('Всё под контролем.','Настройки, подключение Telegram и состояние обработки.',false)}<div class="readable"><section class="paper status-list">${[
 ['Анализ материалов',['gemini','provod'].includes(m.analysis_provider)?'Gemini 3.8 Flash: текст и изображения':'Локальная модель на Mac',m.analysis_provider==='provod'?'Provod':m.analysis_provider==='gemini'?'Google':'Локально',true],
 ['Telegram-бот',`@${m.bot_username}`,m.bot_running?'Работает':m.bot_configured?'Проверь подключение':'Нужен токен',m.bot_running],
 ['Поиск по описанию',m.search_provider==='gemini'?'Gemini через '+(m.analysis_provider==='provod'?'Provod':'Google')+' · запрос и краткие описания материалов':'Локальная модель на Mac',m.search_provider==='gemini'?'Подключён':m.ai_ready?'Подключён':m.ai_error,m.search_provider==='gemini'||m.ai_ready],
 ['Текст и формулы на фотографиях',m.vision_provider==='gemini'?'Gemini видит само изображение':'Локальное распознавание',m.vision_ready?'Подключено':'Не подключено',m.vision_ready],
 ['Текст в PDF','Первые '+(m.pdf_pages||4)+' страницы; текст и изображения','Локально',true],
 ['Личная память','Сохраняет твои пояснения и пересматривает похожие записи','Примеров: '+(m.memory_examples||0),true],
 ['Интернет','Общие понятия при сомнении; до двух источников',m.web_lookup?'Включён':'Выключен',m.web_lookup],
 ['Голосовые','Локальная расшифровка на русском, до трёх минут',m.voice_ready?'Работает локально':'Не подключено',m.voice_ready],
 ['Подборки на телефоне','Проверка внешнего адреса и кнопки Telegram',m.phone_access?.ready?'Доступны':m.phone_access?.required?'Восстанавливаем подключение':'Пока на Mac',!!m.phone_access?.ready]
 ].map(([title,desc,status,good])=>`<div class="status-row"><div><strong>${esc(title)}</strong><p>${esc(desc)}</p></div><span class="status-label ${good?'good':''}">${esc(status)}</span></div>`).join('')}</section>${provodPanel()}${geminiPanel()}${m.bot_error?`<div class="inline-note">${esc(m.bot_error)}</div>`:''}${m.local&&!m.bot_configured?'<div class="paper"><h3>Подключение бота</h3><p class="form-note">В папке проекта есть файл «Настройки.env». Вставь токен в строку BOT_TOKEN= и перезапусти программу. Токен сюда вводить не нужно.</p></div>':''}${m.pair_link?`<section class="paper"><h3>Подключить тебя как владельца</h3><p class="form-note">После добавления токена открой личную ссылку и нажми «Старт». Ссылка даёт доступ владельца — не пересылай её другим.</p><a class="primary" href="${esc(m.pair_link)}" target="_blank" rel="noreferrer">Открыть своего бота ${ic('arrow')}</a></section>`:''}${m.owner&&m.paired?'<section class="paper"><h3>Пригласить тестировщика</h3><p class="form-note">Одно приглашение — один человек. Действует 24 часа. Его материалы будут доступны только ему.</p><button class="secondary" data-action="invite">Создать приглашение</button><div id="invite-output"></div></section>':''}<section class="paper"><h3>Твои данные</h3><p class="form-note">Обычные материалы хранятся на этом Mac. Пароли хранятся отдельным зашифрованным блоком. Удалённое остаётся в корзине, пока ты его не восстановишь.</p><div class="toolbar"><button class="secondary" data-action="export">${ic('download')}Экспортировать записи</button><button class="secondary" data-action="trash">${ic('trash')}Корзина</button><button class="ghost" data-action="reindex">Переразобрать материалы</button></div><p class="form-note">Экспорт содержит текст и сведения о материалах, а также зашифрованный блок паролей. Оригинальные вложения нужно сохранять отдельно. Резервную копию всей базы делай при остановленной программе.</p></section></div>`}
function vault(){if(!unlocked){const exists=!!vaultData.envelope;return `<section class="vault-entry">${hero('Пароли — под замком.','Один защищённый раздел рядом с остальными сохранениями.',false)}<form id="unlock-form" class="vault-hero"><div class="lock-emblem">${ic('lock')}</div><h2>${exists?'Открыть хранилище':'Создать хранилище'}</h2><p>${exists?'Введи главный пароль. Он открывает зашифрованное хранилище.':'Придумай отдельный главный пароль — минимум 8 символов. Главный пароль остаётся на устройстве.'}</p><input class="input" id="master-password" type="password" maxlength="1000" placeholder="Главный пароль" aria-label="Главный пароль" autocomplete="${exists?'current-password':'new-password'}" required minlength="${exists?1:8}">${!exists?'<input class="input" id="master-confirm" type="password" placeholder="Повтори пароль" aria-label="Повтор главного пароля" autocomplete="new-password" required minlength="8">':''}${vaultData.bot_setup_allowed?`<label class="form-note vault-check"><input type="checkbox" name="bot-access" ${vaultData.bot_access_requested===false?'':'checked'}><span>Выдавать логин и пароль по названию сервиса в Telegram.</span></label>`:''}<div class="vault-submit"><button class="primary" type="submit">${ic('lock')}${exists?'Разблокировать':'Создать и открыть'}</button></div><div id="vault-error" class="form-error" role="alert"></div><p class="form-note">${exists?'Автоблокировка через 2 минуты бездействия и при сворачивании.':'Восстановления главного пароля нет. Сохрани его отдельно: без него расшифровать данные не получится.'}</p></form><p class="form-note readable">Пароли добавляются здесь, а не сообщением боту. Шифрование AES-GCM выполняется в приложении до отправки серверу. Этот раздел — первая тестовая реализация; пока проверяй его на вымышленных данных.</p></section>`}
 return `${hero('Только для тебя.','Хранилище открыто на этом устройстве.',false)}${vaultBotPanel()}<div class="actions"><button class="primary" data-action="vault-add">${ic('plus')}Добавить пароль</button><button class="secondary" data-action="vault-master">Изменить главный пароль</button><button class="secondary" data-action="vault-lock">${ic('lock')}Заблокировать</button></div><div class="searchbox">${ic('search')}<input id="vault-search" aria-label="Поиск в открытом хранилище" placeholder="Название сервиса или логин…" autocomplete="off"></div><p class="form-note">Поиск в этом разделе выполняется на устройстве. Секреты не попадают в общий поиск.</p><div class="items" id="vault-items">${vaultItems('')}</div>`}
function vaultBotPanel(){return `<div class="paper"><h3>Пароли в Telegram</h3><p class="form-note">${vaultData.bot_access?'Включено. Напиши боту название сервиса или «данные рхту». Логин и пароль придут под спойлером; сообщение удалится через 5 минут. Доступ работает и после закрытия этого окна.':'Выключено. Нажми «Включить выдачу в Telegram» и введи главный пароль. Это можно сделать на телефоне.'} Пароли не отправляются в Gemini. Спойлер скрывает текст на экране; чат с ботом не имеет сквозного шифрования.</p>${vaultData.bot_access&&vaultData.bot_setup_allowed?'<button class="secondary small" data-action="vault-bot-off">Выключить выдачу в Telegram</button>':vaultData.bot_setup_allowed?'<button class="primary" data-action="vault-bot-on">Включить выдачу в Telegram</button>':''}</div>`}
function vaultItems(q){const entries=unlocked.entries.filter(e=>(e.title+' '+e.login).toLowerCase().includes(q.toLowerCase()));return entries.length?entries.map(e=>`<div class="vault-item">${ic('lock')}<div><strong>${esc(e.title)}</strong><small>${esc(e.login)}</small></div><button class="secondary small" data-action="vault-show" data-id="${esc(e.id)}">Открыть</button></div>`).join(''):empty('Здесь пока пусто','Добавь пароль через кнопку выше.',false)}
function trashPage(){return `${hero('Корзина','Удалённые материалы можно восстановить.',false)}<button class="back" data-action="nav" data-page="settings">${ic('back')}Настройки</button>${state.items.length?state.items.map(i=>`<div class="item"><span class="item-icon">${ic(i.kind)}</span><span class="item-content"><span class="item-title">${esc(i.title)}</span></span><button class="secondary small" data-action="restore" data-id="${i.id}">Восстановить</button></div>`).join(''):empty('Корзина пуста','Здесь появятся удалённые материалы.',false)}`}
function render(){if(activePreview){URL.revokeObjectURL(activePreview);activePreview=null}document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="wordmark" href="#" data-action="nav" data-page="home"><img class="brandmark logo-image" src="/static/logo.png" alt=""><span>Из<em>brain</em>ое</span></a>${nav()}<div class="sidebar-note"><strong><span class="dot"></span>Твоё личное пространство</strong>Материалы на Mac.<br>${['gemini','provod'].includes(state.me.analysis_provider)?'Анализ через Gemini.':'Без платных API.'}</div></aside><main class="main">${phoneBanner()}${learningBanner()}${({home,collections,detail,settings,vault,trash:trashPage}[state.page]||home)()}</main>${nav(true)}</div>`;if(state.page==='detail')loadPreview()}
async function refreshMe(){state.me=await api('/me')}
async function loadItems(append=false){const request=++state.request;const params=new URLSearchParams({q:state.q,group:state.group,kind:state.kind,document_type:state.docType,offset:append?state.items.length:0,limit:state.page==='home'&&!state.q?8:40,trash:state.page==='trash'});const data=await api('/items?'+params);if(request!==state.request)return;state.items=append?[...state.items,...data.items]:data.items;state.total=data.total;state.searchMode=data.mode;state.searchWarning=data.warning||''}
async function go(page,options={}){const navigation=++state.navigation;if(state.page==='vault'&&page!=='vault')lockVault(false);state.page=page;state.group=options.group||'';state.kind='';state.docType='';state.q=options.q||'';state.detail=null;await refreshMe();if(['home','collections','trash'].includes(page))await loadItems();if(page==='vault')vaultData=await api('/vault');if(navigation!==state.navigation)return;render();window.scrollTo(0,0)}
async function openItem(id){const navigation=++state.navigation;const from={page:state.page,group:state.group,q:state.q};const item=await api('/items/'+id);if(navigation!==state.navigation)return;state.detail={...item,from};state.page='detail';render();window.scrollTo(0,0)}
function applyDetail(item,id,from){if(!item||item.id!==id||state.page!=='detail'||state.detail?.id!==id)return false;state.detail={...item,from};render();return true}

async function loadPreview(){const i=state.detail;try{const r=await fetch('/api/items/'+i.id+'/preview',{headers:initData?{Authorization:'tma '+initData}:{}});if(!r.ok)return;const blob=await r.blob();if(state.detail?.id!==i.id||state.page!=='detail')return;activePreview=URL.createObjectURL(blob);const p=document.querySelector('#preview');if(p)p.innerHTML=i.kind==='photo'?`<div class="paper"><img class="preview-image" src="${activePreview}" alt="Сохранённое изображение"></div>`:`<div class="paper">${i.kind==='video'?'<video class="preview-video" src="'+activePreview+'" controls preload="metadata"></video>':'<audio class="preview-audio" src="'+activePreview+'" controls></audio>'}</div>`}catch{}}
function modal(title,body,submit='Сохранить',id='modal-form'){lastFocus=document.activeElement;document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Закрыть">${ic('close')}</button></div><form id="${id}">${body}<div id="form-error" class="form-error" role="alert"></div>${submit?`<div class="modal-footer"><button type="button" class="ghost" data-action="close-modal">Отмена</button><button class="primary" type="submit">${esc(submit)}</button></div>`:''}</form></section></div>`;document.querySelector('.modal input,.modal textarea,.modal button')?.focus()}
function closeModal(){document.querySelector('#modal-root').innerHTML='';lastFocus?.focus()}
function addModal(){modal('Добавить в Изbrainое',`<div class="filters"><button type="button" class="filter active" data-action="add-note">Заметка или ссылка</button><button type="button" class="filter" data-action="add-file">Файл</button></div><label for="note-text">Что сохранить</label><textarea id="note-text" name="text" placeholder="Вставь текст, ссылку или мысль…" required maxlength="50000"></textarea><p class="form-note">Пароли и секреты добавляй в защищённом разделе.</p>`,'Сохранить','note-form')}
function fileModal(){modal('Добавить файл',`<div class="upload-zone">${ic('upload')}<p>Фото, PDF, документы, таблицы, архивы, аудио и видео — до ${state.me.max_upload_mb||100} МБ</p><input type="file" name="file" aria-label="Выбрать файл" required></div><label for="file-context">Пояснение, если нужно</label><textarea id="file-context" name="context" placeholder="Например: договор на обучение, первый курс" maxlength="10000"></textarea>`,'Загрузить','file-form')}
function editModal(){const i=state.detail;modal('Контекст и папка',`<label for="edit-title">Название</label><input class="input" id="edit-title" name="title" value="${esc(i.title)}" required maxlength="200"><label for="edit-context">Твоё пояснение</label><textarea id="edit-context" name="context" maxlength="10000" placeholder="Что это и с чем связано">${esc(i.context)}</textarea><label for="edit-groups">Основная папка</label><input class="input" id="edit-groups" name="groups" value="${esc(i.groups[0]||'')}" placeholder="Высшая математика" maxlength="40"><p class="form-note">Выбери тему без подразделов: например «Высшая математика». Тип материала выбирается фильтром внутри папки. Ручной выбор закрепится. Пояснение помогает разобрать также похожие материалы. Точное слово «удалить» переместит эту запись в корзину.</p><label><input type="checkbox" name="automatic"> Заново выбрать папку автоматически</label>`,'Сохранить','edit-form')}
async function download(path,filename){const r=await fetch('/api'+path,{headers:initData?{Authorization:'tma '+initData}:{}});if(!r.ok){let d;try{d=await r.json()}catch{}throw Error(d?.detail||'Не удалось скачать файл.')}const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function touchVault(){clearTimeout(vaultTimer);if(unlocked)vaultTimer=setTimeout(()=>lockVault(),120000)}
function lockVault(show=true){unlocked=null;clearTimeout(vaultTimer);if(state.page==='vault'){closeModal();if(show){render();toast('Хранилище заблокировано')}}}
async function saveVault(entries){const envelope=await encryptVault(unlocked.key,unlocked.salt,entries);const result=await api('/vault',{method:'PUT',body:{version:vaultData.version,envelope,lookup_tokens:await lookupTokens(entries)}});vaultData={...vaultData,version:result.version,envelope};unlocked.entries=entries;touchVault()}
async function enableBotAccess(password){const challenge=await api('/vault/bot-access-key');const grant=await wrapBotKey(password,vaultData.envelope.salt,challenge,vaultData.version);await api('/vault/bot-access',{method:'POST',body:{...grant,lookup_tokens:await lookupTokens(unlocked.entries)}});vaultData.bot_access=true;vaultData.bot_access_requested=true}
function vaultModal(entry){modal(entry?'Данные для входа':'Добавить пароль',`<label for="v-title">Название сервиса</label><input class="input" id="v-title" name="title" value="${esc(entry?.title||'')}" required maxlength="120" autocomplete="off"><label for="v-login">Логин</label><input class="input" id="v-login" name="login" value="${esc(entry?.login||'')}" maxlength="300" autocomplete="off"><label for="v-aliases">Другие названия сервиса</label><input class="input" id="v-aliases" name="aliases" value="${esc(entry?.aliases||'')}" maxlength="200" placeholder="Например: рхту, личный кабинет"><label for="v-password">Пароль</label><input class="input" id="v-password" name="password" type="password" value="${esc(entry?.password||'')}" required maxlength="2000" autocomplete="off"><div class="actions"><button type="button" class="secondary small" data-action="toggle-secret">${ic('eye')}Показать</button><button type="button" class="secondary small" data-action="copy-secret">${ic('copy')}Скопировать</button></div><label for="v-notes">Заметка</label><textarea id="v-notes" name="notes" maxlength="5000">${esc(entry?.notes||'')}</textarea><input type="hidden" name="id" value="${esc(entry?.id||'')}">${entry?`<button type="button" class="ghost small" data-action="vault-delete" data-id="${esc(entry.id)}">${ic('trash')}Удалить запись</button>`:''}<p class="form-note">Все поля шифруются на устройстве. Для начала используй вымышленные данные.</p>`,'Сохранить','vault-entry-form')}

document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();const a=el.dataset.action;try{
 if(a==='nav')await go(el.dataset.page);
 else if(a==='group')await go('collections',{group:el.dataset.group});
 else if(a==='reset-filters'){state.kind='';state.docType='';await loadItems();render()}
 else if(a==='filter'){state.kind=el.dataset.kind;await loadItems();render()}
 else if(a==='type-filter'){state.docType=el.dataset.type;await loadItems();render()}
 else if(a==='search-all')await go('home',{q:state.q});
 else if(a==='item')await openItem(el.dataset.id);
 else if(a==='back'){const f=state.detail?.from||{page:'home'};await go(f.page,{group:f.group,q:f.q})}
 else if(a==='add'||a==='add-note')addModal();
 else if(a==='add-file')fileModal();
 else if(a==='close-modal')closeModal();
 else if(a==='edit')editModal();
 else if(a==='analyse-again'){el.disabled=true;el.textContent='Читаем и анализируем…';const item=state.detail;if(!item)return;const id=item.id;const from=item.from;const updated=await api('/items/'+id+'/analyse',{method:'POST'});await refreshMe();applyDetail(updated,id,from);toast('Материал проанализирован заново')}
 else if(a==='attach-original'){modal('Добавить оригинал',`<p class="form-note">Файл будет связан с этой записью. Для PDF прочитаю первые ${state.me.pdf_pages||4} страницы. До ${state.me.max_upload_mb||100} МБ.</p><input class="input" type="file" name="file" required aria-label="Выбрать оригинал">`,'Загрузить','attach-form')}

 else if(a==='delete'){modal('Переместить в корзину?',`<p class="sub">«${esc(state.detail.title)}» исчезнет из подборок и поиска. Восстановить можно в настройках.</p>`,'В корзину','delete-form')}
 else if(a==='restore'){await api('/items/'+el.dataset.id+'/restore',{method:'POST'});await loadItems();await refreshMe();render();toast('Материал восстановлен')}
 else if(a==='trash')await go('trash');
 else if(a==='more'){el.disabled=true;await loadItems(true);render()}
 else if(a==='download')await download('/items/'+el.dataset.id+'/file',state.detail.filename||state.detail.title);
 else if(a==='send'){await api('/items/'+el.dataset.id+'/send',{method:'POST'});toast('Отправлено в твой чат с ботом')}
 else if(a==='export')await download('/export','izbrainoe-export.json');
 else if(a==='reconnect-phone'){el.disabled=true;await api('/network/reconnect',{method:'POST'});await refreshMe();render();toast('Восстановление подключения запрошено')}
 else if(a==='reindex'){el.disabled=true;el.textContent='Обновляем…';await api('/reindex',{method:'POST'});await refreshMe();render();toast('Повторный разбор запущен. Прогресс появится сверху.')}
 else if(a==='invite'){const d=await api('/invite',{method:'POST'});document.querySelector('#invite-output').innerHTML=`<p class="form-note">Личная ссылка действует 24 часа:</p><input class="input" readonly value="${esc(d.url)}" aria-label="Ссылка-приглашение"><p class="form-note">Скопируй её и отправь одному тестировщику.</p>`}
 else if(a==='gemini-off'){await api('/ai/local',{method:'POST'});await refreshMe();render();toast('Разбор переключён на локальную модель')}
 else if(a==='vault-lock')lockVault();
 else if(a==='vault-bot-on')modal('Включить выдачу в Telegram',`<p class="form-note">Введи главный пароль. Он останется на устройстве; ключ доступа будет передан на Mac в зашифрованном виде. После этого бот сможет выдать логин и пароль под спойлером на 5 минут.</p><label for="bot-master">Главный пароль</label><input class="input" id="bot-master" name="master" type="password" autocomplete="current-password" required maxlength="1000">`,'Включить выдачу','vault-bot-form');
 else if(a==='vault-bot-off'){await api('/vault/bot-access',{method:'DELETE'});vaultData.bot_access=false;vaultData.bot_access_requested=false;render();toast('Выдача паролей в Telegram выключена')}
 else if(a==='vault-master')modal('Изменить главный пароль',`<label>Новый главный пароль</label><input class="input" type="password" name="password" minlength="8" maxlength="1000" autocomplete="new-password" required><label>Повтори пароль</label><input class="input" type="password" name="confirm" minlength="8" maxlength="1000" autocomplete="new-password" required><p class="form-note">Минимум 8 символов. Данные будут заново зашифрованы новым ключом.</p>`,'Изменить пароль','vault-master-form');
 else if(a==='vault-add')vaultModal(null);
 else if(a==='vault-show')vaultModal(unlocked.entries.find(i=>i.id===el.dataset.id));
 else if(a==='toggle-secret'){const p=document.querySelector('#v-password');p.type=p.type==='password'?'text':'password';el.innerHTML=ic('eye')+(p.type==='password'?'Показать':'Скрыть')}
 else if(a==='copy-secret'){await navigator.clipboard.writeText(document.querySelector('#v-password').value);toast('Пароль скопирован. Буфер обмена содержит секрет.')}
 else if(a==='vault-delete'){const id=el.dataset.id;modal('Удалить пароль?',`<p class="sub">Запись будет удалена из зашифрованного хранилища. Вернуть её можно только из ранее сохранённой резервной копии.</p><input type="hidden" name="id" value="${esc(id)}">`,'Удалить','vault-delete-form')}
 }catch(err){error(err.message);el.disabled=false}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;const formId=form.getAttribute('id');const button=form.querySelector('[type=submit]');const buttonText=button?.textContent;if(button){button.disabled=true;if(formId!=='search-form')button.textContent='Сохраняем…'}const f=new FormData(form);try{
 if(formId==='provod-form'){const key=String(f.get('key')||'').trim();document.querySelector('#provod-key').value='';const result=await api('/ai/provod',{method:'POST',body:{key,monthly_limit_rub:Number(f.get('monthly_limit_rub'))}});await refreshMe();render();toast(result.message)}
 else if(formId==='gemini-form'){const key=String(f.get('key')||'').trim();document.querySelector('#gemini-key').value='';const result=await api('/ai/gemini',{method:'POST',body:{key,monthly_limit_usd:Number(f.get('monthly_limit_usd'))}});await refreshMe();render();toast(result.message)}
 else if(formId==='search-form'){state.q=String(f.get('q')).trim();await loadItems();render();document.querySelector('#search')?.focus()}
 else if(formId==='note-form'){await api('/items',{method:'POST',body:{text:f.get('text')}});closeModal();await go('home');toast('Сохранено')}
 else if(formId==='file-form'){button.textContent='Обрабатываем…';await api('/upload',{method:'POST',body:f});closeModal();await go('home');toast('Файл сохранён')}
 else if(formId==='edit-form'){const i=state.detail;const from=i.from;const gs=[String(f.get('groups')).trim()].filter(Boolean);const payload={title:f.get('title'),context:f.get('context'),automatic:f.has('automatic')};if(JSON.stringify(gs)!==JSON.stringify(i.groups))payload.groups=gs;const updated=await api('/items/'+i.id,{method:'PATCH',body:payload});closeModal();if(updated.deleted){await go('home');toast('Запись перемещена в корзину');return}await refreshMe();applyDetail(updated,i.id,from);toast('Пояснение сохранено. Проверяю похожие записи.')}
 else if(formId==='attach-form'){const i=state.detail;const from=i.from;const updated=await api('/items/'+i.id+'/attach',{method:'POST',body:f});closeModal();await refreshMe();applyDetail(updated,i.id,from);toast('Оригинал добавлен и проанализирован')}

 else if(formId==='delete-form'){const from=state.detail.from;await api('/items/'+state.detail.id,{method:'DELETE'});closeModal();await go(from.page,{group:from.group,q:from.q});toast('Перемещено в корзину')}
 else if(formId==='unlock-form'){
   const p=document.querySelector('#master-password').value;document.querySelector('#master-password').value='';
   if(!crypto.subtle)throw Error('Для шифрования нужен HTTPS или локальный адрес на Mac.');
   if(vaultData.envelope){try{unlocked=await decryptVault(p,vaultData.envelope)}catch{throw Error('Не удалось открыть хранилище. Проверь главный пароль.')}}
   else{const confirm=document.querySelector('#master-confirm').value;document.querySelector('#master-confirm').value='';if(p.length<8||p!==confirm)throw Error('Пароли должны совпадать и содержать минимум 8 символов.');const salt=crypto.getRandomValues(new Uint8Array(16));unlocked={key:await derive(p,salt),salt,entries:[]};try{await saveVault([])}catch(err){unlocked=null;throw err}}
   if(vaultData.bot_setup_allowed){if(f.has('bot-access')){try{await enableBotAccess(p)}catch(err){vaultData.bot_access=false;touchVault();render();toast('Хранилище открыто. Выдача в Telegram не включена: '+err.message);return}}else{await api('/vault/bot-access',{method:'DELETE'});vaultData.bot_access=false;vaultData.bot_access_requested=false}}
   touchVault();render();
 }
 else if(formId==='vault-bot-form'){if(!unlocked)throw Error('Хранилище заблокировано.');await enableBotAccess(String(f.get('master')||''));closeModal();render();toast('Выдача включена. Напиши боту название сервиса.')}
 else if(formId==='vault-master-form'){if(!unlocked)throw Error('Хранилище заблокировано.');const p=String(f.get('password'));if(p.length<8||p!==f.get('confirm'))throw Error('Пароли должны совпадать и содержать минимум 8 символов.');const salt=crypto.getRandomValues(new Uint8Array(16));const key=await derive(p,salt);const envelope=await encryptVault(key,salt,unlocked.entries);const result=await api('/vault',{method:'PUT',body:{version:vaultData.version,envelope}});unlocked={...unlocked,key,salt};vaultData={...vaultData,version:result.version,envelope};closeModal();if(vaultData.bot_access){try{await enableBotAccess(p)}catch{vaultData.bot_access=false;render();throw Error('Главный пароль изменён. Для выдачи в Telegram заблокируй хранилище и открой его новым паролем.')}}render();toast('Главный пароль изменён')}
 else if(formId==='vault-entry-form'){if(!unlocked)throw Error('Хранилище заблокировано.');const id=f.get('id')||crypto.randomUUID();const entry={id,title:f.get('title'),login:f.get('login'),aliases:f.get('aliases'),password:f.get('password'),notes:f.get('notes')};const entries=unlocked.entries.filter(i=>i.id!==id).concat(entry);await saveVault(entries);closeModal();render();toast('Запись зашифрована и сохранена')}
 else if(formId==='vault-delete-form'){await saveVault(unlocked.entries.filter(i=>i.id!==f.get('id')));closeModal();render();toast('Запись удалена')}
 }catch(err){const target=form.querySelector('#form-error,#vault-error');if(target)target.textContent=err.message;else error(err.message)}finally{if(button){button.disabled=false;if(formId!=='search-form')button.textContent=buttonText}}});
document.addEventListener('change',async e=>{if(!['purpose-filter','format-filter'].includes(e.target.id))return;const key=e.target.id==='purpose-filter'?'docType':'kind';state[key]=e.target.value;try{await loadItems();if(state.page==='collections')render()}catch(err){error(err.message)}});
document.addEventListener('input',e=>{if(e.target.id==='vault-search'&&unlocked)document.querySelector('#vault-items').innerHTML=vaultItems(e.target.value)});
document.addEventListener('keydown',e=>{touchVault();if(e.key==='Escape'){if(document.querySelector('.modal'))closeModal();else if(unlocked)lockVault()}if(e.key==='Tab'&&document.querySelector('.modal')){const items=[...document.querySelectorAll('.modal button,.modal input,.modal textarea')].filter(e=>!e.disabled&&e.type!=='hidden');const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
document.addEventListener('pointerdown',touchVault);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&unlocked)lockVault()});
window.addEventListener('pagehide',()=>lockVault(false));

async function boot(){try{
 if(location.hash.includes('tgWebAppData')){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://telegram.org/js/telegram-web-app.js';s.onload=resolve;s.onerror=reject;document.head.append(s)});telegram=window.Telegram?.WebApp;initData=telegram?.initData||'';telegram?.ready();telegram?.expand()}
 await go('home');const params=new URLSearchParams(location.search);if(['settings','vault'].includes(params.get('page')))await go(params.get('page'));const target=params.get('item');if(target&&/^[a-f0-9]{32}$/.test(target))await openItem(target);
 }catch(err){document.querySelector('#app').innerHTML=`<div class="error-screen"><span class="brandmark">и.</span><h1>Твоё Изbrainое</h1><p class="sub">${esc(err.message||'Не удалось открыть приложение.')}</p><p class="form-note">На Mac используй файл «Запустить Изbrainое.command». На телефоне — кнопку «Подборки» в боте.</p><a class="primary" href="https://t.me/izbrainoe_bot" target="_blank" rel="noreferrer">Открыть бота ${ic('arrow')}</a></div>`}}
setInterval(async()=>{if(!state.me||!['queued','running'].includes(state.me.learning?.status)||state.page==='vault'||document.querySelector('.modal'))return;try{await refreshMe();const banner=document.querySelector('.learning-status');if(banner)banner.outerHTML=learningBanner();if(!['queued','running'].includes(state.me.learning?.status)&&['home','collections'].includes(state.page)&&!document.activeElement?.matches('input,textarea')){await loadItems();render()}}catch{}},5000);
boot();

setInterval(async()=>{if(!state.me||document.querySelector('.modal'))return;try{await refreshMe();const banner=document.querySelector('#phone-status');if(banner)banner.outerHTML=phoneBanner()}catch{}},15000);

setInterval(async()=>{const item=state.detail;if(state.page!=='detail'||item?.analysis_state!=='retry_pending'||document.querySelector('.modal'))return;try{const updated=await api('/items/'+item.id);applyDetail(updated,item.id,item.from)}catch{}},5000);
